def total_fruit(fruits):
    n = len(fruits)
    best = 0
    for start in range(n):
        types = set()
        end = start
        while end < n:
            types.add(fruits[end])                                       # try extending the window by one more tree
            if len(types) > 2:
                break                                                        # a third type appeared, this start can't extend further
            end += 1
        best = max(best, end - start)
    return best


if __name__ == "__main__":
    print(total_fruit([1, 2, 3, 2, 2]))

