import java.util.*;

public class Main {
    int totalFruit(int[] fruits) {
        int n = fruits.length;
        int best = 0;
        for (int start = 0; start < n; start++) {
            Set<Integer> types = new HashSet<>();
            int end = start;
            while (end < n) {
                types.add(fruits[end]);                                          // try extending the window by one more tree
                if (types.size() > 2) break;                                       // a third type appeared, this start can't extend further
                end++;
            }
            best = Math.max(best, end - start);
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.totalFruit(new int[]{1, 2, 3, 2, 2}));
    }
}

