        count[fruit] = count.get(fruit, 0) + 1                            # add this tree's fruit type to the window
        while len(count) > 2:                                              # more than 2 distinct types, shrink from the left
            count[fruits[left]] -= 1
            if count[fruits[left]] == 0:
                del count[fruits[left]]
            left += 1
        best = max(best, right - left + 1)
    return best


