public class Main {
    int totalFruit(int[] fruits) {
        Map<Integer, Integer> count = new HashMap<>();
        int left = 0;
        int best = 0;
        for (int right = 0; right < fruits.length; right++) {
            count.merge(fruits[right], 1, Integer::sum);                          // add this tree's fruit type to the window
            while (count.size() > 2) {                                              // more than 2 distinct types, shrink from the left
                int leaving = fruits[left];
                count.merge(leaving, -1, Integer::sum);
                if (count.get(leaving) == 0) count.remove(leaving);
                left++;
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.totalFruit(new int[]{1, 2, 3, 2, 2}));
    }
}

