#include <bits/stdc++.h>
using namespace std;

int totalFruit(vector<int>& fruits) {
    unordered_map<int,int> count;
    int left = 0;
    int best = 0;
    for (int right = 0; right < (int)fruits.size(); right++) {
        count[fruits[right]]++;                                                  // add this tree's fruit type to the window
        while ((int)count.size() > 2) {                                            // more than 2 distinct types, shrink from the left
            int leaving = fruits[left];
            count[leaving]--;
            if (count[leaving] == 0) count.erase(leaving);
            left++;
        }
        best = max(best, right - left + 1);
    }
    return best;
}

int main() {
    vector<int> fruits = {1, 2, 3, 2, 2};
    cout << totalFruit(fruits) << endl;
    return 0;
}
